eSpace P.gluedOver.left := by\n    change IrreducibleSpace P.glueData.glued\n    infer_instance\n  exact GroupScheme.finiteInAffine_of_isAlgClosed_of_irreducible P.gluedOver\n\n/-- The represented group law produces orbit affineness on the exact finite-stage carrier\nover an algebraically closed field, with no projective-space immersion hypothesis. -/\n@[implicit_reducible]\nnoncomputable def\n    pic0FiniteStageOrbitsInAffineOpen_of_isAlgClosed_of_irreducible\n    (P : Pic0FiniteStageGluePackage Ck F)\n    [Algebra K P.N.1] [FiniteDimensional K P.N.1] [IsGalois K P.N.1]\n    [IsAlgClosed P.N.1] [IrreducibleSpace P.glueData.glued]\n    (rep : (pic0TypeFunctor ((baseChange K P.N.1).obj C)).RepresentableBy P.gluedOver) :\n    (pic0SemilinearGalActionOfRepresentableBy C rep).OrbitsInAffineOpen :=\n  Scheme.orbitsInAffineOpen_of_finiteInAffine _\n    (pic0FiniteStageFiniteInAffine_of_isAlgClosed_of_irreducible C Ck P rep)\n\n/-- Over an algebraically closed finite-stage field, connectedness and the represented\ngroup law make the exact glued Picard-zero carrier `FiniteInAffine`. -/\ntheorem pic0FiniteStageFiniteInAffine_of_isAlgClosed_of_connected\n    (P : Pic0FiniteStageGluePackage Ck F)\n    [Algebra K P.N.1] [IsAlgClosed P.N.1]\n    [ConnectedSpace P.glueData.glued]\n    (rep : (pic0TypeFunctor ((baseChange K P.N.1).obj C)).RepresentableBy P.gluedOver) :\n    Scheme.FiniteInAffine P.glueData.glued := by\n  letI : GrpObj P.gluedOver :=\n    pic0FiniteStageGrpObjOfRepresentableBy C Ck P rep\n  letI : LocallyOfFiniteType P.gluedOver.hom := by\n    change LocallyOfFiniteType P.gluedMap\n    infer_instance\n  letI : ConnectedSpace P.gluedOver.left := by\n    change ConnectedSpace P.glueData.glued\n    infer_instance\n  exact GroupScheme.finiteInAffine_of_isAlgClosed_of_connected P.gluedOver\n\n/-- Connectedness of the represented finite-stage group supplies orbit affineness over an\nalgebraically closed field.  No arbitrary-field closure is asserted here. -/\n@[implicit_reducible]\nnoncomputable def\n    pic0FiniteStageOrbitsInAffineOpen_of_isAlgClosed_of_connected\n    (P : Pic0FiniteStageGluePackage Ck F)\n    [Algebra K P.N.1] [FiniteDimensional K P.N.1] [IsGalois K P.N.1]\n    [IsAlgClosed P.N.1] [ConnectedSpace P.glueData.glued]\n    (rep : (pic0TypeFunctor ((baseChange K P.N.1).obj C)).RepresentableBy P.gluedOver) :\n    (pic0SemilinearGalActionOfRepresentableBy C rep).OrbitsInAffineOpen :=\n  Scheme.orbitsInAffineOpen_of_finiteInAffine _\n    (pic0FiniteStageFiniteInAffine_of_isAlgClosed_of_connected C Ck P rep)\n\n/-- A finite-dimensional projective-space immersion makes the finite-stage glue\n`FiniteInAffine`. -/\ntheorem pic0FiniteStageFiniteInAffine_of_isImmersion\n    (P : Pic0FiniteStageGluePackage Ck F)\n    {n : Type u} [Finite n]\n    (i : P.glueData.glued ⟶ ℙ(n; Spec (.of P.N.1)))\n    (hi : IsImmersion i) :\n    Scheme.FiniteInAffine P.glueData.glued := by\n  letI : IsImmersion i := hi\n  exact Scheme.finiteInAffine_of_isImmersion i\n    (Scheme.finiteInAffine_projectiveSpace n (Spec (.of P.N.1)))\n\n/-- A finite-dimensional projective-space immersion supplies orbit affineness for the\ncanonical action attached to a representation of Picard zero by the finite-stage glue. -/\n@[implicit_reducible]\nnoncomputable def pic0FiniteStageOrbitsInAffineOpen_of_isImmersion\n    (P : Pic0FiniteStageGluePackage Ck F)\n    [Algebra K P.N.1] [FiniteDimensional K P.N.1] [IsGalois K P.N.1]\n    (rep : (pic0TypeFunctor ((baseChange K P.N.1).obj C)).RepresentableBy P.gluedOver)\n    {n : Type u} [Finite n]\n    (i : P.glueData.glued ⟶ ℙ(n; Spec (.of P.N.1)))\n    (hi : IsImmersion i) :\n    (pic0SemilinearGalActionOfRepresentableBy C rep).OrbitsInAffineOpen :=\n  Scheme.orbitsInAffineOpen_of_finiteInAffine _\n    (pic0FiniteStageFiniteInAffine_of_isImmersion Ck P i hi)\n\n/-- Compatibility wrapper deriving the immersion input from projectivity of the finite-stage\nglued morphism. -/\n@[implicit_reducible]\nnoncomputable def pic0FiniteStageOrbitsInAffineOpen_of_isProjective\n    (P : Pic0FiniteStageGluePackage Ck F)\n    [Algebra K P.N.1] [FiniteDimensional K P.N.1] [IsGalois K P.N.1]\n    (rep : (pic0TypeFunctor ((baseChange K P.N.1).obj C)).RepresentableBy P.gluedOver)\n    (hproj : P.gluedMap.IsProjective) :\n    (pic0SemilinearGalActionOfRepresentableBy C rep).OrbitsInAffineOpen := by\n  obtain ⟨n, hn, i, hi, -⟩ := hproj\n  letI : Finite n := hn\n  letI : IsClosedImmersion i := hi\n  exact pic0FiniteStageOrbitsInAffineOpen_of_isImmersion C Ck P rep i\n    (inferInstance : IsImmersion i)\n\nend\n\nend AlgebraicGeometry\n\n=== stableorbit ===\n/-\nCopyright (c) 2026 The AlgebraicJacobian Contributors. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: The AlgebraicJacobian Contributors\n-/\nimport AlgebraicJacobian.Descent.GroupAffineOpen\nimport AlgebraicJacobian.Descent.QuasiProjectiveFiniteInAffine\nimport AlgebraicJacobian.Picard.Pic0FiniteStageStableGluePackage\nimport AlgebraicJacobian.Picard.Pic0GaloisAction\n\n/-!\n# Orbit affineness for a stable finite-stage Picard glue\n\nThese producers use the carrier and structure map selected by a\n`Pic0FiniteStageStableGluePackage`.  In particular, this module does not reconstruct or import\nthe legacy finite-stage glue package.\n-/\n\nset_option autoImplicit false\n\nuniverse u\n\nopen CategoryTheory\nopen AlgebraicJacobian.GaloisDescent\n\nnamespace AlgebraicGeometry\n\nnoncomputable section\n\nvariable {K k F : Type u} [Field K] [Field k] [Field F]\nvariable [Algebra F k] [Algebra.IsAlgebraic F k]\nvariable (C : Over (Spec (.of K)))\nvariable [SmoothOfRelativeDimension 1 C.hom] [IsProper C.hom]\n  [GeometricallyIrreducible C.hom]\nvariable (Ck : Over (Spec (.of k)))\nvariable [SmoothOfRelativeDimension 1 Ck.hom] [IsProper Ck.hom]\n  [GeometricallyIrreducible Ck.hom] [IsSepClosed k]\n\n/-- The group object transported to the carrier selected by a stable glue presentation. -/\n@[implicit_reducible]\nnoncomputable def pic0FiniteStageStableGrpObjOfRepresentableBy\n    (P : Pic0FiniteStageStableGluePackage Ck F)\n    [Algebra K P.context.triple.N.1]\n    (rep : (pic0TypeFunctor ((baseChange K P.context.triple.N.1).obj C)).RepresentableBy\n      P.presentation.over) :\n    GrpObj P.presentation.over :=\n  GrpObj.ofRepresentableBy P.presentation.over\n    (pic0Functor ((baseChange K P.context.triple.N.1).obj C) ⋙\n      forget₂ CommGrpCat GrpCat) rep\n\n/-- Stable-package form of the irreducible algebraic-group orbit producer.\n\nLocal finite type is explicit because a stable package deliberately permits an arbitrary\nselected affine presentation; that geometric property is not encoded in the package itself. -/\n@[implicit_reducible]\nnoncomputable def\n    pic0FiniteStageStableOrbitsInAffineOpen_of_isAlgClosed_of_irreducible\n    (P : Pic0FiniteStageStableGluePackage Ck F)\n    [Algebra K P.context.triple.N.1]\n    [FiniteDimensional K P.context.triple.N.1] [IsGalois K P.context.triple.N.1]\n    [IsAlgClosed P.context.triple.N.1]\n    [LocallyOfFiniteType P.presentation.map]\n    [IrreducibleSpace P.presentation.glueData.glued]\n    (rep : (pic0TypeFunctor ((baseChange K P.context.triple.N.1).obj C)).RepresentableBy\n      P.presentation.over) :\n    (pic0SemilinearGalActionOfRepresentableBy C rep).OrbitsInAffineOpen := by\n  letI : GrpObj P.presentation.over :=\n    pic0FiniteStageStableGrpObjOfRepresentableBy C Ck P rep\n  letI : LocallyOfFiniteType P.presentation.over.hom := by\n    change LocallyOfFiniteType P.presentation.map\n    infer_instance\n  letI : IrreducibleSpace P.presentation.over.left := by\n    change IrreducibleSpace P.presentation.glueData.glued\n    infer_instance\n  exact Scheme.orbitsInAffineOpen_of_finiteInAffine _\n    (GroupScheme.finiteInAffine_of_isAlgClosed_of_irreducible P.presentation.over)\n\n/-- Stable-package form of the connected algebraic-group orbit producer. -/\n@[implicit_reducible]\nnoncomputable def\n    pic0FiniteStageStableOrbitsInAffineOpen_of_isAlgClosed_of_connected\n    (P : Pic0FiniteStageStableGluePackage Ck F)\n    [Algebra K P.context.triple.N.1]\n    [FiniteDimensional K P.context.triple.N.1] [IsGalois K P.context.triple.N.1]\n    [IsAlgClosed P.context.triple.N.1]\n    [LocallyOfFiniteType P.presentation.map]\n    [ConnectedSpace P.presentation.glueData.glued]\n    (rep : (pic0TypeFunctor ((baseChange K P.context.triple.N.1).obj C)).RepresentableBy\n      P.presentation.over) :\n    (pic0SemilinearGalActionOfRepresentableBy C rep).OrbitsInAffineOpen := by\n  letI : GrpObj P.presentation.over :=\n    pic0FiniteStageStableGrpObjOfRepresentableBy C Ck P rep\n  letI : LocallyOfFiniteType P.presentation.over.hom := by\n    change …10474 tokens truncated…Top_tower\n#check AlgebraicGeometry.PicRankOneLocalPresentation.datumSectionBaseChange_tower\n#check AlgebraicGeometry.PicRankOneLocalPresentation.baseOpenRankOneDivisor_mul_eq\n#check AlgebraicGeometry.PicRankOneNativePresentation.ofCertificates\n#check AlgebraicGeometry.PicRankOneLocalPresentation.evaluation\n#check AlgebraicGeometry.PicRankOneLocalPresentation.nativeBaseChangeIso\n#check AlgebraicGeometry.PicRankOneLocalPresentation.nativeBaseChangeIsoAffine\n#check AlgebraicGeometry.PicRankOneLocalPresentation.evaluationSourceBaseChangeIso\n#check AlgebraicGeometry.PicRankOneLocalPresentation.evaluationSourceBaseChangeIso_hom_evaluation\n#check\n  AlgebraicGeometry.PicRankOneLocalPresentation.evaluationSourceBaseChangeIsoAffine_hom_evaluation\n#check AlgebraicGeometry.PicRankOneLocalPresentation.datumSection\n#check AlgebraicGeometry.PicRankOneLocalPresentation.datumSectionBaseChange\n#check AlgebraicGeometry.PicRankOneLocalPresentation.datumSectionBaseChange_one_tmul\n#check AlgebraicGeometry.PicRankOneLocalPresentation.datumSectionBaseChangeLinearMap\n#check\n  AlgebraicGeometry.PicRankOneLocalPresentation.datumSectionBaseChange_eq_smul_of_tensor_eq\n#check\n  AlgebraicGeometry.PicRankOneLocalPresentation.tensorAwayGe