Prefer horizon search and sibling formalizations before inventing parallel infrastructure.\",\n      \"scope\": {},\n      \"audience\": \"horizon\",\n      \"author\": \"human\",\n      \"owner_task\": \"\",\n      \"read_by\": [\n        \"ajcr-finite-stage-api-redesign\",\n        \"fs-stacks-part08-modulitheory\",\n        \"fs-mumford\",\n        \"fs-hartshorne\",\n        \"fs-milne\",\n        \"fs-stacks-part01-prelim\",\n        \"fs-stacks-part06-deform\",\n        \"fs-stacks-part04-alg-spaces\",\n        \"fs-stacks-part03-scheme-topicstheory\",\n        \"fs-stacks-part07-alg-stacks\",\n        \"fs-stacks-part05-geom-topics\",\n        \"fs-stacks-part02-schemes\"\n      ],\n      \"source_ref\": null,\n      \"created_at\": \"2026-08-27T08:27:30.090374+00:00\",\n      \"updated_at\": \"2026-08-27T15:09:54.668439+00:00\",\n      \"comments\": [],\n      \"metadata\": {\n        \"read_by\": [\n          \"ajcr-finite-stage-api-redesign\",\n          \"fs-stacks-part08-modulitheory\",\n          \"fs-mumford\",\n          \"fs-hartshorne\",\n          \"fs-milne\",\n          \"fs-stacks-part01-prelim\",\n          \"fs-stacks-part06-deform\",\n          \"fs-stacks-part04-alg-spaces\",\n          \"fs-stacks-part03-scheme-topicstheory\",\n          \"fs-stacks-part07-alg-stacks\",\n          \"fs-stacks-part05-geom-topics\",\n          \"fs-stacks-part02-schemes\"\n        ],\n        \"history\": [\n          {\n            \"at\": \"2026-08-27T08:27:30.092397+00:00\",\n            \"actor\": \"human\",\n            \"field\": \"created\",\n            \"from\": \"\",\n            \"to\": \"open\",\n            \"note\": \"opened\"\n          },\n          {\n            \"at\": \"2026-08-27T08:30:51.765182+00:00\",\n            \"actor\": \"horizon\",\n            \"field\": \"read_by\",\n            \"from\": \"\",\n            \"to\": \"read\",\n            \"note\": \"\",\n            \"provenance\": {\n              \"run\": \"0163\",\n         